        grey |= (grey << 16) | (grey << 8);
        size = random_float_between(1.0f, 1.02f);
        puff = PartType23Spawn(&pos, (*(float *)&D_L08_00161A30), 1.0f, size, rand_range(-2, 2), &vel,
                                grow + size0 * 210000.0f, (alpha << 24) | grey);
